      probeNoRound: "القاعدة الحاكمة: يقع بلا باقٍ أو يُرفض باسمه — ولا تقريب في الحالتين. «١٢ حبّة ← كرتون» تُجيب «١»، و«٧ حبّات ← كرتون» تُرفض ولا تُجيب «0.583333». والسبب أن الكمّية تُضرب في تكلفة الوحدة، فالتقريب فيها يدخل **المال** ويتراكم على كل حركة حتى يصير الرصيد لا يساوي مجموع حركاته — ولا يُظهره توازنٌ ولا سلسلةُ بصمات.",
