      nextClassMismatch: "الوحدتان من صنفَي كمّية مختلفين. سجّل معاملاً بين وحدتين من الصنف نفسه، أو أرسل الكمّية بوحدةٍ من صنف الوجهة — ولا تُسجَّل كثافةُ مادّةٍ بوصفها معاملاً ثابتاً.",
      nextNoConversion: "لا معامل مسجَّل بين هاتين الوحدتين، ولا يُشتقّ بسلسلةٍ من معاملين. سجّله صراحةً في لوح معاملات التحويل أدناه.",
      nextOverflow: "الناتج يتجاوز مدى العدد العشري المخزَّن، والرقم الذي لا يُمثَّل لا يُقرَّب ولا يُقتطع. أرسل مقداراً أصغر، أو أرسله بوحدةٍ أكبر.",
      nextDuplicateCode: "رمز الوحدة مستعمَل في هذه المنشأة. اختر رمزاً آخر — وقد تكون الوحدة موجودةً مُعطَّلةً في الجدول أعلاه.",
      nextDuplicateConversion: "يوجد معامل بين هاتين الوحدتين. ومعاملان لزوجٍ واحد تعريفان متناقضان لواقعةٍ فيزيائية واحدة، ولا يُقرَّر أيّهما يُقرأ.",
